RtPipeline::~RtPipeline(){Destroy();}
VkShaderModule RtPipeline::CreateShader(const std::vector<uint32_t>& code) const{if(code.empty())return VK_NULL_HANDLE;VkShaderModuleCreateInfo i{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};i.codeSize=code.size()*sizeof(uint32_t);i.pCode=code.data();VkShaderModule m=VK_NULL_HANDLE;return vkCreateShaderModule(device_,&i,nullptr,&m)==VK_SUCCESS?m:VK_NULL_HANDLE;}
